<?php require 'config/config.php';auth();$s=db()->prepare("SELECT a.*,b.move_in_date,b.months,b.advance_amount,r.room_number,r.rent,p.title,p.address,p.city,o.name owner,t.name tenant,t.email tenant_email,t.phone tenant_phone FROM rental_agreements a JOIN bookings b ON b.id=a.booking_id JOIN rooms r ON r.id=b.room_id JOIN properties p ON p.id=r.property_id JOIN users o ON o.id=p.owner_id JOIN users t ON t.id=b.user_id WHERE a.id=? AND b.user_id=?");$s->execute([(int)$_GET['id'],user()['id']]);$a=$s->fetch();if(!$a)exit('Agreement not found');$title='Rental Agreement';require 'config/header.php';?><div class="agreementTop"><div><small>GENERATED AFTER PAYMENT</small><h1>Rental Agreement</h1><p>Agreement No: <?=e($a['agreement_no'])?></p></div><a class="btn" href="<?=BASE_URL?>/agreement_pdf.php?id=<?=$a['id']?>">Download PDF</a></div><div class="agreement panel"><h2>SmartStay Residential Rental Agreement</h2><table><tr><th>Tenant</th><td><?=e($a['tenant'])?><br><?=e($a['tenant_email'])?><br><?=e($a['tenant_phone'])?></td></tr><tr><th>Owner</th><td><?=e($a['owner'])?></td></tr><tr><th>Property</th><td><?=e($a['title'])?><br><?=e($a['address'])?>, <?=e($a['city'])?></td></tr><tr><th>Room</th><td><?=e($a['room_number'])?></td></tr><tr><th>Move-in</th><td><?=date('d M Y',strtotime($a['move_in_date']))?></td></tr><tr><th>Period</th><td><?=e($a['months'])?> month(s)</td></tr><tr><th>Monthly rent</th><td><?=money($a['rent'])?></td></tr><tr><th>Advance paid</th><td><?=money($a['advance_amount'])?></td></tr><tr><th>Payment reference</th><td><?=e($a['payment_transaction_id'])?></td></tr></table><h3>Terms</h3><ol><li>Residential use only.</li><li>Tenant agrees to pay monthly rent on time.</li><li>Tenant will maintain the room and report major issues.</li><li>Changes should be recorded by both parties.</li><li>This is a project-generated digital agreement.</li></ol><div class="sign"><span>Tenant<br><b><?=e($a['tenant'])?></b></span><span>Owner<br><b><?=e($a['owner'])?></b></span></div></div><?php require 'config/footer.php';?>
